      options:[
        'Choose the idea suggested by the most influential group member',
        'Select the solution that sounds most exciting without further investigation',
        'Compare the solutions using criteria such as relevance, cost, feasibility, community acceptance, impact and sustainability',
        'Choose the solution that requires the greatest amount of money'
      ],
      correct:2
